{
  "mode": "compile",
  "question": null,
  "asks_about": "tolerance",
  "unresolved": [],
  "understanding": "The job is a pre-ride safety inspection and inflation of the Segway Xyber tyres to the maximum pressure printed on the sidewall. The rider visually checks for sidewall cracks, inflates the tyres, documents the pressure with a photo of the gauge and sidewall, and signs off before riding.",
  "draft": {
    "key": "pre-ride-tyre-check",
    "title": "Pre-Ride Tyre Inspection and Inflation",
    "strictness": 2,
    "minimum_tier": "open",
    "disqualifiers": [
      "Cracked or split tyre sidewall"
    ],
    "releases": [
      "Safe to ride on city traffic and gravel"
    ],
    "steps": [
      {
        "title": "Visual Inspection",
        "explanation": "Checking for cracks or splits in the sidewall prevents a sudden tyre failure at speed in traffic.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "sidewall_check",
            "kind": "choice",
            "prompt": "Inspect both tyres for cracks or splits in the sidewall.",
            "source": "human",
            "required_at_strictness": 2,
            "choices": [
              "Pass - sidewalls are clear",
              "Fail - cracks or splits found"
            ],
            "acceptance_rule": "matches",
            "acceptance_target": "Pass - sidewalls are clear",
            "guidance": "Look closely at both sides of the front and rear tyres. Any visible cracking or splitting means the tyre must be replaced."
          }
        ]
      },
      {
        "title": "Inflation and Pressure Verification",
        "explanation": "Inflating to the sidewall limit ensures the tyre performs safely under load without risking a blowout.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "pressure_photo",
            "kind": "photo",
            "prompt": "Take a photo showing the pressure gauge reading alongside the max pressure printed on the tyre sidewall.",
            "source": "camera",
            "required_at_strictness": 2,
            "acceptance_rule": "must_show",
            "acceptance_description": "The photo must clearly show the gauge needle or digital readout aligned with the maximum pressure limit printed on the tyre sidewall.",
            "guidance": "Hold the gauge near the tyre sidewall markings so both the target pressure and the actual pressure are visible in one clear shot."
          }
        ]
      },
      {
        "title": "Rider Sign-off",
        "explanation": "The rider must personally confirm they are satisfied with the tyre condition before entering traffic.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "rider_signature",
            "kind": "signature",
            "prompt": "Sign to confirm the tyres are safe for your ride.",
            "source": "human",
            "required_at_strictness": 2,
            "acceptance_rule": "signed_by",
            "acceptance_target": "Rider",
            "guidance": "Your signature confirms you have inspected both tyres and verified the pressure."
          }
        ]
      }
    ]
  }
}
